use std::f64::consts::{PI, TAU};

#[derive(Clone, Copy, Debug)]
struct Pt { x: f64, y: f64 }

fn round_away(x: f64) -> i64 { if x >= 0.0 { (x + 0.5).floor() as i64 } else { (x - 0.5).ceil() as i64 } }
fn area(poly: &[(i64,i64)]) -> f64 {
    let mut a: i128 = 0;
    for i in 0..poly.len() {
        let (x1,y1)=poly[i];
        let (x2,y2)=poly[(i+1)%poly.len()];
        a += x1 as i128 * y2 as i128 - y1 as i128 * x2 as i128;
    }
    a as f64 / 2.0
}
fn unit_normal(a: Pt, b: Pt) -> Pt {
    let dx = b.x - a.x;
    let dy = b.y - a.y;
    let f = (dx*dx + dy*dy).sqrt();
    Pt { x: dy / f, y: -dx / f }
}
fn dot(a: Pt, b: Pt) -> f64 { a.x*b.x + a.y*b.y }
fn cross(a: Pt, b: Pt) -> f64 { a.x*b.y - a.y*b.x }

fn do_round(poly: &[Pt], delta: f64, arc_tol: f64, use_round_steps: bool, use_global_step: bool) -> Vec<(i64,i64)> {
    let n = poly.len();
    let mut norms = Vec::new();
    for i in 0..n {
        norms.push(unit_normal(poly[i], poly[(i+1)%n]));
    }
    let steps_per_360 = if arc_tol <= 0.0 || arc_tol > delta.abs() {
        PI / (1.0 - 0.25 / delta.abs()).acos()
    } else {
        PI / (1.0 - arc_tol / delta.abs()).acos()
    };
    let steps_per_rad = steps_per_360 / TAU;
    let step_ang = TAU / steps_per_360;
    let mut out = Vec::new();
    for j in 0..n {
        let k = if j==0 { n-1 } else { j-1 };
        let nk = norms[k];
        let nj = norms[j];
        let mut a = cross(nk, nj).atan2(dot(nk, nj));
        if a < 0.0 { a += TAU; }
        let ext = a; // maybe exterior
        let stepsf = steps_per_rad * ext.abs();
        let steps = if use_round_steps { stepsf.round().max(1.0) as i32 } else { stepsf.ceil().max(1.0) as i32 };
        let (mut x, mut y) = (nk.x, nk.y);
        let (step_cos, step_sin) = if use_global_step {
            let s = if ext < 0.0 { -step_ang.sin() } else { step_ang.sin() };
            (step_ang.cos(), s)
        } else {
            let ang = ext / steps as f64;
            (ang.cos(), ang.sin())
        };
        out.push((round_away(poly[j].x + x*delta), round_away(poly[j].y + y*delta)));
        for _ in 0..steps-1 {
            let x2 = x*step_cos - step_sin*y;
            let y2 = x*step_sin + y*step_cos;
            x = x2; y = y2;
            out.push((round_away(poly[j].x + x*delta), round_away(poly[j].y + y*delta)));
        }
        out.push((round_away(poly[j].x + nj.x*delta), round_away(poly[j].y + nj.y*delta)));
    }
    out.dedup();
    out
}
fn main() {
    let poly = [Pt{x:50.0,y:0.0}, Pt{x:100.0,y:100.0}, Pt{x:0.0,y:100.0}];
    for &(arc_tol, rs, gs) in &[(0.25,true,true),(0.25,false,true),(0.25,true,false),(0.1,true,true),(0.5,true,true)] {
        let mut err = 0.0;
        for o in 0..=20 {
            let out = std::process::Command::new("/workspace/dataset/test7_executable").arg(o.to_string()).output().unwrap();
            let s = String::from_utf8(out.stdout).unwrap();
            let target: f64 = s.trim().parse().unwrap();
            let pts = do_round(&poly, o as f64, arc_tol, rs, gs);
            let a = area(&pts).abs();
            err += (a-target).abs();
        }
        println!("arc_tol={arc_tol} rs={rs} gs={gs} err={err}");
    }
}
