use std::f64::consts::{PI, TAU};

#[derive(Clone, Copy)]
struct Pt{ x:f64, y:f64 }

fn round_mode(x:f64, mode:i32)->i64{
    match mode {
        0 => if x>=0.0 { (x+0.5).floor() as i64 } else { (x-0.5).ceil() as i64 }, // away
        1 => x.round() as i64, // Rust away? actually away from zero
        2 => x.floor() as i64,
        3 => x.ceil() as i64,
        4 => (x+0.5).floor() as i64, // symmetric floor+0.5 (bad for neg)
        _ => unreachable!(),
    }
}
fn area(poly:&[(i64,i64)])->f64{let mut a:i128=0;for i in 0..poly.len(){let(x1,y1)=poly[i];let(x2,y2)=poly[(i+1)%poly.len()];a+=x1 as i128*y2 as i128-y1 as i128*x2 as i128;} (a.abs() as f64)/2.0}
fn unit_normal(a:Pt,b:Pt)->Pt{let dx=b.x-a.x;let dy=b.y-a.y;let f=(dx*dx+dy*dy).sqrt();Pt{x:dy/f,y:-dx/f}}
fn dot(a:Pt,b:Pt)->f64{a.x*b.x+a.y*b.y}
fn cross(a:Pt,b:Pt)->f64{a.x*b.y-a.y*b.x}
fn eff_tol(delta:f64, kind:i32, c:f64)->f64{match kind{0=>c,1=>c*(2.0+delta.abs()).log10(),2=>c*(2.0+delta.abs()).ln(),3=>c*delta.abs().sqrt(),4=>c*delta.abs(),_=>0.25}}
fn steps360(delta:f64, tol:f64, form:i32)->f64{match form{0=>PI/(1.0-(tol.min(delta.abs()))/delta.abs()).acos(),1=>TAU/(1.0-(tol.min(delta.abs()))/delta.abs()).acos(),2=>PI/((0.5*tol.min(delta.abs())/delta.abs()).acos()),_=>0.0}}
fn sim(delta:i32, tol_kind:i32, c:f64, steps_form:i32, steps_mode:i32, rot_mode:i32, round:i32)->f64{
    let poly=[Pt{x:50.0,y:0.0},Pt{x:100.0,y:100.0},Pt{x:0.0,y:100.0}];
    let deltaf=delta as f64;
    if delta==0 { return 5000.0; }
    let norms=[unit_normal(poly[0],poly[1]),unit_normal(poly[1],poly[2]),unit_normal(poly[2],poly[0])];
    let tol=eff_tol(deltaf,tol_kind,c);
    let sp360=steps360(deltaf,tol,steps_form);
    let spr=sp360/TAU;
    let global_step=TAU/sp360;
    let mut out=Vec::new();
    for j in 0..3 {
        let k=(j+2)%3; let nk=norms[k]; let nj=norms[j];
        let mut ang=cross(nk,nj).atan2(dot(nk,nj)); if ang<0.0{ang+=TAU;}
        let base=spr*ang.abs();
        let steps=match steps_mode{0=>base.round(),1=>base.ceil(),2=>base.floor(),_=>1.0}.max(1.0) as i32;
        let (step_cos,step_sin)=match rot_mode{0=>(global_step.cos(),global_step.sin()),1=>{let s=ang/(steps as f64);(s.cos(),s.sin())},2=>{let s=ang/((steps+1) as f64);(s.cos(),s.sin())},_=>unreachable!()};
        let mut x=nk.x; let mut y=nk.y;
        out.push((round_mode(poly[j].x+x*deltaf,round),round_mode(poly[j].y+y*deltaf,round)));
        for _ in 0..steps-1 { let x2=x*step_cos-step_sin*y; let y2=x*step_sin+step_cos*y; x=x2; y=y2; out.push((round_mode(poly[j].x+x*deltaf,round),round_mode(poly[j].y+y*deltaf,round))); }
        out.push((round_mode(poly[j].x+nj.x*deltaf,round),round_mode(poly[j].y+nj.y*deltaf,round)));
    }
    // remove consecutive dups
    let mut ded=Vec::new();
    for p in out { if ded.last().copied()!=Some(p){ded.push(p);} }
    if ded.first()==ded.last(){ ded.pop(); }
    area(&ded)
}
fn main(){
    let mut targets=[0.0f64; 51];
    for o in 0..=50 { let out=std::process::Command::new("/workspace/dataset/test7_executable").arg(o.to_string()).output().unwrap(); let s=String::from_utf8(out.stdout).unwrap(); targets[o as usize]=s.trim().parse().unwrap(); }
    let mut best:Vec<(f64,String)>=Vec::new();
    for tol_kind in 0..=4 {
        for ci in 1..=100 {
            let c = ci as f64 / 100.0;
            for steps_form in 0..=1 {
                for steps_mode in 0..=2 {
                    for rot_mode in 0..=2 {
                        for round in 0..=4 {
                            let mut err=0.0; let mut maxe=0.0; let mut exact=0;
                            for o in 0..=50 { let a=sim(o as i32,tol_kind,c,steps_form,steps_mode,rot_mode,round); let e=(a-targets[o]).abs(); err += e; if e>maxe {maxe=e}; if e<1e-9 { exact +=1; } }
                            let desc=format!("tol_kind={tol_kind} c={c:.2} sf={steps_form} sm={steps_mode} rm={rot_mode} round={round} exact={exact} maxe={maxe}");
                            if best.len()<20 || err < best.last().unwrap().0 {
                                best.push((err, desc));
                                best.sort_by(|a,b| a.0.partial_cmp(&b.0).unwrap());
                                best.truncate(20);
                            }
                        }
                    }
                }
            }
        }
    }
    for (err,desc) in best { println!("err={err} {desc}"); }
}
