use std::f64::consts::{PI, TAU};

#[derive(Clone, Copy, Debug, PartialEq)]
struct PtD{ x:f64, y:f64 }
#[derive(Clone, Copy, Debug, PartialEq)]
struct PtI{ x:i64, y:i64 }

fn get_unit_normal(a:PtI,b:PtI)->PtD{
    if a==b { return PtD{x:0.0,y:0.0}; }
    let dx=(b.x-a.x) as f64; let dy=(b.y-a.y) as f64; let inv=1.0/(dx.hypot(dy));
    PtD{x:dy*inv,y:-dx*inv}
}
fn roundpt(x:f64,y:f64)->PtI{ PtI{x:x.round() as i64,y:y.round() as i64} }
fn perpendic(p:PtI,n:PtD,delta:f64)->PtI{ roundpt(p.x as f64 + n.x*delta, p.y as f64 + n.y*delta) }
fn area(poly:&[PtI])->f64{ let mut a:i128=0; for i in 0..poly.len(){let p=poly[i]; let q=poly[(i+1)%poly.len()]; a += p.x as i128*q.y as i128 - p.y as i128*q.x as i128;} (a.abs() as f64)/2.0 }
fn offset(delta_in:i32, delta_sign:f64)->Vec<PtI>{
    let path=[PtI{x:50,y:0},PtI{x:100,y:100},PtI{x:0,y:100}];
    let mut normals=Vec::new();
    for i in 0..path.len()-1{ normals.push(get_unit_normal(path[i], path[i+1])); }
    normals.push(get_unit_normal(path[path.len()-1], path[0]));
    let delta = delta_sign * delta_in as f64;
    let mut out=Vec::new();
    let mut k=path.len()-1;
    for j in 0..path.len(){
        if path[j]==path[k] { k=j; continue; }
        let mut sin_a = normals[j].x*normals[k].y - normals[j].y*normals[k].x;
        let cos_a = normals[j].x*normals[k].x + normals[j].y*normals[k].y;
        if sin_a > 1.0 { sin_a=1.0; } else if sin_a < -1.0 { sin_a=-1.0; }
        if delta.abs() <= 1e-12 {
            out.push(path[j]);
        } else if cos_a > -0.999 && delta * sin_a < 0.0 {
            out.push(perpendic(path[j], normals[k], delta));
            out.push(path[j]);
            out.push(perpendic(path[j], normals[j], delta));
        } else if cos_a > 0.999 && (/*join_type != round*/ false) {
            unreachable!();
        } else {
            let angle = sin_a.atan2(cos_a);
            // DoRound exact from disassembly without callback path
            let delta_abs = delta.abs();
            let arc_tol = delta_abs * 0.002;
            let steps_per_360 = (PI*delta_abs).min(PI / (1.0 - arc_tol/delta_abs).acos());
            let step_angle = TAU / steps_per_360;
            let step_sin = if delta < 0.0 { -step_angle.sin() } else { step_angle.sin() };
            let step_cos = step_angle.cos();
            let steps_per_rad = steps_per_360 / TAU;
            let mut offset = PtD{x:normals[k].x*delta, y:normals[k].y*delta};
            if j==k { offset = PtD{x:-offset.x,y:-offset.y}; }
            out.push(roundpt(path[j].x as f64 + offset.x, path[j].y as f64 + offset.y));
            let steps = (angle.abs()*steps_per_rad).ceil() as i32;
            for _ in 1..steps {
                let x = offset.x*step_cos - offset.y*step_sin;
                let y = offset.x*step_sin + offset.y*step_cos;
                offset = PtD{x,y};
                out.push(roundpt(path[j].x as f64 + offset.x, path[j].y as f64 + offset.y));
            }
            out.push(perpendic(path[j], normals[j], delta));
        }
        k=j;
    }
    // mimic possible duplicate cleanup? none here
    out
}
fn main(){
    for sign in [1.0,-1.0] {
        let mut err=0.0;
        println!("sign {sign}");
        for o in 0..=20 { let out=std::process::Command::new("/workspace/dataset/test7_executable").arg(o.to_string()).output().unwrap(); let s=String::from_utf8(out.stdout).unwrap(); let target:f64=s.trim().parse().unwrap(); let pts=offset(o,sign); let a=area(&pts); err += (a-target).abs(); println!("o={o} a={a} target={target} diff={} n={} pts={:?}", a-target, pts.len(), if o<=2 { format!("{:?}", pts) } else { String::new() }); }
        println!("err {err}");
    }
}
